#!/usr/bin/env bash
# Generated by: Claude Opus 5.5
# Generation date: 2026-10-11
#
# Shared helpers for run-server.sh, stop-server.sh and compare.sh. Source, don't run.
# Uses only commands and flags supported by both SingularityCE and Apptainer.

SINGULARITY=${SINGULARITY:-singularity}
IMAGE_REPO=jmtovar/local_llm_images
MODELS=(base ministral-3-3b gemma4-e4b)

die() { echo "error: $*" >&2; exit 1; }

require() {
  local cmd
  for cmd in "$@"; do
    command -v "$cmd" >/dev/null 2>&1 || die "'$cmd' is required but not installed"
  done
}

check_model() {
  local m
  for m in "${MODELS[@]}"; do [[ "$1" == "$m" ]] && return 0; done
  die "unknown model '$1' (expected: ${MODELS[*]})"
}

# Semver, digits only: X.Y.Z, X.Y.Z-alpha.N or X.Y.Z-beta.N (no leading zeros)
check_version() {
  local n='(0|[1-9][0-9]*)'
  [[ "$1" == v* ]] && die "version '$1': use plain digits without a 'v' prefix, e.g. ${1#v}"
  [[ "$1" =~ ^$n\.$n\.$n(-(alpha|beta)\.$n)?$ ]] \
    || die "version '$1' is not X.Y.Z, X.Y.Z-alpha.N or X.Y.Z-beta.N"
}

is_release() { [[ "$1" =~ ^[0-9]+\.[0-9]+\.[0-9]+$ ]]; }

sif_path() { echo "${LLM_SIF_DIR:?LLM_SIF_DIR must be set}/ollama-$1_$2.sif"; }

# Highest X.Y.Z release of ollama-<model> on GHCR; falls back to local SIFs offline.
# Prereleases are never picked; name one explicitly to use it.
latest_release() {
  local model=$1 image="$IMAGE_REPO/ollama-$1" token tags latest f v
  if token=$(curl -fsS --max-time 15 "https://ghcr.io/token?scope=repository:$image:pull" 2>/dev/null | jq -r '.token') \
    && tags=$(curl -fsS --max-time 15 -H "Authorization: Bearer $token" \
      "https://ghcr.io/v2/$image/tags/list?n=1000" 2>/dev/null | jq -r '.tags[]?'); then
    latest=$(grep -E '^[0-9]+\.[0-9]+\.[0-9]+$' <<<"$tags" | sort -V | tail -n 1 || true)
  fi
  if [[ -n "${latest:-}" ]]; then
    echo "$latest"
    return 0
  fi

  echo "note: GHCR not reachable or no release found; using newest local SIF" >&2
  local versions=()
  for f in "${LLM_SIF_DIR:?LLM_SIF_DIR must be set}/ollama-${model}_"*.sif; do
    [[ -e "$f" ]] || continue
    v=${f##*/ollama-"${model}"_}
    v=${v%.sif}
    if is_release "$v"; then versions+=("$v"); fi
  done
  if (( ${#versions[@]} > 0 )); then
    printf '%s\n' "${versions[@]}" | sort -V | tail -n 1
  fi
}

resolve_version() {
  local model=$1 version=${2:-latest}
  if [[ "$version" == latest ]]; then
    version=$(latest_release "$model") || true
    [[ -n "$version" ]] || die "no release of ollama-$model found on GHCR or in $LLM_SIF_DIR"
  fi
  check_version "$version"
  echo "$version"
}

# Image path of a running instance, empty if not running.
# Parses the plain table (NAME PID IP IMAGE), which both runtimes print.
instance_image() {
  "$SINGULARITY" instance list 2>/dev/null | awk -v n="$1" '$1 == n { print $NF }'
}

server_up() { curl -fsS --max-time 2 "http://127.0.0.1:$1/api/version" >/dev/null 2>&1; }
